// Filter emails that have audio attachments and return one item per audio file.
// Supports: mp3, wav, m4a, ogg, webm, opus, aac, flac, wma
const AUDIO_EXTENSIONS = /\.(mp3|wav|m4a|ogg|webm|opus|aac|flac|wma)$/i;
const AUDIO_MIME = ['audio/', 'video/mp4', 'video/webm', 'video/ogg'];

const result = [];

for (const item of $input.all()) {
  const attachments = item.json.attachments || [];

  for (let i = 0; i < attachments.length; i++) {
    const att = attachments[i];
    const isAudio =
      AUDIO_MIME.some(t => (att.mimeType || '').startsWith(t)) ||
      AUDIO_EXTENSIONS.test(att.filename || '');

    if (!isAudio) continue;

    result.push({
      json: {
        replyTo: item.json.from,
        subject: item.json.subject || '(no subject)',
        date: item.json.date,
        audioFilename: att.filename || `recording_${i}.audio`,
        audioMimeType: att.mimeType || 'audio/mpeg',
        binaryKey: `attachment_${i}`
      },
      binary: item.binary
    });

    break; // One audio file per email — process first one found
  }
}

if (result.length === 0) {
  // No audio attachments — nothing to do
  return [];
}

return result;
